// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account/v1/agreements", wrapper.ListAgreements)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account/v1/me/consents", wrapper.ListConsents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/me/consents", wrapper.AcceptAgreements)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/register", wrapper.Register)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account/v1/me", wrapper.GetAccount)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account/v1/me/identity-verification", wrapper.GetIdentityVerification)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/me/identity-verification", wrapper.SubmitIdentityVerification)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account/v1/me/invitations", wrapper.ListMyInvitations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/me/invitations/accept", wrapper.AcceptInvitationByToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/me/invitations/{invitationId}/accept", wrapper.AcceptInvitation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/account/v1/projects", wrapper.ListProjects)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/projects", wrapper.CreateProject)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/account/v1/projects/{projectId}/token", wrapper.ExchangeProjectToken)

	return m
}

